function biggestDivisibleGroup(nums: number[]): number[] {
  const n = nums.length;
  let best: number[] = [];
  for (let mask = 1; mask < 1 << n; mask++) {
    const pick: number[] = [];
    for (let b = 0; b < n; b++) if (mask & (1 << b)) pick.push(nums[b]);
    if (pick.length <= best.length) continue;
    let ok = true;
    for (let i = 0; i < pick.length && ok; i++)
      for (let j = i + 1; j < pick.length && ok; j++)
        if (pick[i] % pick[j] !== 0 && pick[j] % pick[i] !== 0) ok = false;
    if (ok) best = pick;
  }
  return best;
}

