class Solution:
    def biggestDivisibleGroup(self, nums: List[int]) -> List[int]:
        n, best = len(nums), []
        for mask in range(1, 1 << n):
            pick = [nums[b] for b in range(n) if mask >> b & 1]
            if len(pick) <= len(best):
                continue
            if all(x % y == 0 or y % x == 0 for x, y in itertools.combinations(pick, 2)):
                best = pick
        return best

