function biggestDivisibleGroup(nums: number[]): number[] {
  const a = [...nums].sort((x, y) => x - y);
  const n = a.length;
  const len = new Array(n).fill(1), parent = new Array(n).fill(-1);
  let end = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (a[i] % a[j] === 0 && len[j] + 1 > len[i]) { len[i] = len[j] + 1; parent[i] = j; }
    }
    if (len[i] > len[end]) end = i;
  }
  const out: number[] = [];
  for (let i = end; i !== -1; i = parent[i]) out.push(a[i]);
  return out.reverse();
}

