class Solution:
    def biggestDivisibleGroup(self, nums: List[int]) -> List[int]:
        a = sorted(nums)
        n = len(a)
        length, parent = [1] * n, [-1] * n
        end = 0
        for i in range(n):
            for j in range(i):
                if a[i] % a[j] == 0 and length[j] + 1 > length[i]:
                    length[i], parent[i] = length[j] + 1, j
            if length[i] > length[end]:
                end = i
        out = []
        while end != -1:
            out.append(a[end])
            end = parent[end]
        return out[::-1]

